/**
 * @enum {string}
 */
const TabName = {
	AUTOGENERATED: "autogenerated",
	LIST: "list",
	PUBLISHED: "published",
	README: "readme",
	SEARCH: "search",
	SOURCE: "source",
	TREE: "tree",
};

/**
 * Build the `/targets/...` URL that lists every BCR target using a given
 * callable symbol. Returns "" when the symbol has no file label.
 *
 * @param {!File} file
 * @param {!Symbol} sym
 * @returns {string}
 */
function makeUsagesUrl(file, sym) {
	const label = file.getLabel();
	if (!label) return "";
	return "/targets/" + loadLabelToUrlKey(label, sym.getName());
}

class DocsSelect extends ContentSelect {
	/**
	 * @param {!Registry} registry
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(registry, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const @type {!Registry} */
		this.registry_ = registry;

		/** @private @const @type {!Map<string,!ModuleVersion>} */
		this.docsMap_ = createDocumentationMap(registry);
	}

	/**
	 * @override
	 */
	createDom() {
		this.setElementInternal(soy.renderAsElement(docsSelect));
	}

	/**
	 * @override
	 * @param {!Route} route
	 */
	goHere(route) {
		this.select(TabName.LIST, route.add(TabName.LIST));
	}

	/**
	 * @override
	 * @param {string} name
	 * @param {!Route} route
	 */
	selectFail(name, route) {
		if (name === TabName.LIST) {
			this.addTab(
				TabName.LIST,
				new DocsMapSelectNav(this.registry_, this.docsMap_, this.dom_),
			);
			this.select(name, route);
			return;
		}

		// seek to rewrite paths like `/docs/bazel_lib/3.0.1` to
		// `/modules/bazel_lib/3.0.1/docs`
		const rest = route.unmatchedPath();
		if (rest.length === 2) {
			rest.unshift("modules");
			rest.push("docs");
			route.done(this);
			getApplication(this).setLocation(rest);
			return;
		}

		super.selectFail(name, route);
	}
}
exports.DocsSelect = DocsSelect;

class DocsMapSelectNav extends SelectNav {
	/**
	 * @param {!Registry} registry
	 * @param {!Map<string,!ModuleVersion>} docsMap
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(registry, docsMap, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const @type {!Registry} */
		this.registry_ = registry;

		/** @private @const @type {!Map<string,!ModuleVersion>} */
		this.docsMap_ = docsMap;
	}

	/**
	 * @override
	 */
	createDom() {
		const modules = createModuleMap(this.registry_);
		const maintainers = createMaintainersMap(this.registry_);
		let totalModuleVersions = 0;
		for (const module of modules.values()) {
			totalModuleVersions += module.getVersionsList().length;
		}
		this.setElementInternal(
			soy.renderAsElement(docsMapSelectNav, {
				registry: this.registry_,
				totalModules: modules.size,
				totalModuleVersions: totalModuleVersions,
				totalMaintainers: maintainers.size,
				totalPeople: computeTotalPeople(this.registry_),
				totalSymbols: computeTotalSymbols(this.registry_),
				topPrimaryLanguages: computeTopPrimaryLanguages(this.registry_, 10),
				totalBazelVersions: computeTotalBazelVersions(this.registry_),
				uiCommitSha: uiCommitSha,
			}),
		);
	}

	/**
	 * @override
	 * @param {!Route} route
	 */
	goHere(route) {
		this.select(TabName.PUBLISHED, route.add(TabName.PUBLISHED));
	}

	/**
	 * @override
	 */
	enterDocument() {
		super.enterDocument();

		this.enterPublishedTab();
		this.enterAutogeneratedTab();
		this.enterSearchTab();
	}

	enterSearchTab() {
		this.addNavTabLazy(
			TabName.SEARCH,
			"Search",
			"Search symbols",
			undefined,
			`${this.getPathUrl()}/${TabName.SEARCH}`,
			() => new DocumentationSearchComponent(this.registry_, this.dom_),
		);
	}

	enterPublishedTab() {
		const published = this.getPublishedDocs();
		this.addNavTabLazy(
			TabName.PUBLISHED,
			"Official Published Documentation",
			"Documentation from published latest module versions",
			published.length,
			`${this.getPathUrl()}/${TabName.PUBLISHED}`,
			() => new DocsMapComponent(published, this.dom_),
		);
	}

	enterAutogeneratedTab() {
		const autogenerated = this.getAutogeneratedDocs();
		this.addNavTabLazy(
			TabName.AUTOGENERATED,
			"Auto-generated Documentation",
			"Documentation generated from latest module versions",
			autogenerated.length,
			`${this.getPathUrl()}/${TabName.AUTOGENERATED}`,
			() => new DocsMapComponent(autogenerated, this.dom_),
		);
	}

	/**
	 * @returns {!Array<!ModuleVersion>}
	 */
	getPublishedDocs() {
		const result = [];
		this.docsMap_.forEach((moduleVersion) => {
			const docs = moduleVersion.getSource()?.getDocumentation();
			if (
				docs &&
				docs.getSource() === SymbolSource.PUBLISHED &&
				moduleVersion.getIsLatestVersion()
			) {
				result.push(moduleVersion);
			}
		});
		return result;
	}

	/**
	 * @returns {!Array<!ModuleVersion>}
	 */
	getAutogeneratedDocs() {
		const result = [];
		this.docsMap_.forEach((moduleVersion) => {
			const docs = moduleVersion.getSource()?.getDocumentation();
			if (
				docs &&
				docs.getSource() === SymbolSource.BEST_EFFORT &&
				moduleVersion.getIsLatestVersion()
			) {
				result.push(moduleVersion);
			}
		});
		return result;
	}

	/**
	 * @override
	 * @returns {string}
	 */
	getDefaultTabName() {
		return TabName.PUBLISHED;
	}
}

