class ModuleVersionSymbolsSelect extends ContentSelect {
	/**
	 * @param {!Module} module
	 * @param {!ModuleVersion} moduleVersion
	 * @param {?ModuleVersionSymbols} symbols
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(module, moduleVersion, symbols, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const @type {!Module} */
		this.module_ = module;

		/** @private @const */
		this.moduleVersion_ = moduleVersion;

		/** @private @const @type {?ModuleVersionSymbols} */
		this.symbols_ = symbols;

		/** @const @private @type {!Trie<!File>}*/
		this.fileTrie_ = new Trie();

		/** @const @private @type {!Map<string, {file: !File, sym: !Symbol}>} */
		this.symbolIndex_ = new Map();

		if (symbols) {
			for (const file of symbols.getFileList()) {
				this.addFile(file);
				for (const sym of file.getSymbolList()) {
					this.symbolIndex_.set(sym.getName(), { file, sym });
				}
			}
		}
	}

	/**
	 * @param {!File} file
	 */
	addFile(file) {
		const prefix = this.getFilePrefix(file);
		// Use set instead of add to handle duplicate file paths
		this.fileTrie_.set(prefix, file);
	}

	/**
	 * @param {!File} file
	 * @returns {string}
	 */
	getFilePrefix(file) {
		return `${file.getLabel().getPkg() ? file.getLabel().getPkg() + "/" : ""}${file.getLabel().getName()}`;
	}

	/**
	 * If the current module version is not the latest, returns the latest
	 * version string. Otherwise returns null.
	 * @return {?string}
	 * @private
	 */
	getNewerVersionString_() {
		const latest = getLatestModuleVersion(this.module_);
		if (!latest) return null;
		const latestStr = latest.getVersion();
		if (latestStr === this.moduleVersion_.getVersion()) return null;
		return latestStr;
	}

	/**
	 * @override
	 */
	createDom() {
		const newerVersion = this.getNewerVersionString_();
		const latestUrl = newerVersion
			? `/modules/${this.moduleVersion_.getName()}/${newerVersion}/docs`
			: undefined;

		if (!this.symbols_) {
			this.setElementInternal(
				soy.renderAsElement(documentationBlankslate, {
					latestVersion: newerVersion || undefined,
					latestVersionUrl: latestUrl,
				}),
			);
			return;
		}

		const fileSymbols = buildFileSymbolGroups(this.symbols_);
		if (fileSymbols.length === 0) {
			this.setElementInternal(
				soy.renderAsElement(documentationBlankslate, {
					detail: "Symbol data not available",
					latestVersion: newerVersion || undefined,
					latestVersionUrl: latestUrl,
				}),
			);
			return;
		}

		const navSymbolGroups = buildNavSymbolGroups(fileSymbols);
		const extractionStats = computeExtractionStats(this.symbols_);

		this.setElementInternal(
			soy.renderAsElement(
				documentationInfoSelect,
				{
					module: this.module_,
					moduleVersion: this.moduleVersion_,
					fileSymbols,
					navSymbolGroups,
					info: this.symbols_,
					extractionStats,
				},
				{
					baseUrl: this.getPathUrl(),
				},
			),
		);
	}

	/**
	 * @return {boolean} true when there are file symbols to render — i.e. the
	 * non-blankslate code path in {@link createDom}.
	 * @private
	 */
	hasFileSymbols_() {
		return !!this.symbols_ && buildFileSymbolGroups(this.symbols_).length > 0;
	}

	/**
	 * @override
	 * @param {!Route} route
	 */
	goHere(route) {
		if (!this.hasFileSymbols_()) {
			// Blankslate is the whole content; no sub-tab to route into.
			route.done(this);
			return;
		}
		this.select(TabName.LIST, route.add(TabName.LIST));
	}

	/**
	 * @override
	 * @param {string} name
	 * @param {!Route} route
	 */
	selectFail(name, route) {
		if (name === TabName.README) {
			this.addTab(
				name,
				new DocumentationReadmeComponent(
					this.module_,
					this.moduleVersion_,
					this.dom_,
				),
			);
			this.select(name, route);
			return;
		}

		if (this.symbols_ && buildFileSymbolGroups(this.symbols_).length > 0) {
			if (name === TabName.LIST) {
				this.addTab(
					name,
					new ModuleVersionSymbolsListComponent(
						this.moduleVersion_,
						this.symbols_,
						this.dom_,
					),
				);
				this.select(name, route);
				return;
			}
			if (name === TabName.TREE) {
				this.addTab(
					name,
					new ModuleVersionSymbolsTreeComponent(
						this.moduleVersion_,
						this.symbols_,
						this.dom_,
					),
				);
				this.select(name, route);
				return;
			}

			// try to find the longest matching prefix by popping path elements off
			// the remaining part of the route URL.
			const unmatched = route.unmatchedPath();
			while (unmatched.length) {
				const prefix = unmatched.join("/");
				const file = this.fileTrie_.get(prefix);
				if (file) {
					let tab = this.getTab(prefix);
					if (!tab) {
						tab = this.addTab(
							prefix,
							new FileSelect(
								this.module_,
								this.moduleVersion_,
								file,
								this.symbolIndex_,
								this.dom_,
							),
						);
					}
					this.showTab(prefix);
					tab.go(route.advance(unmatched.length - 1));
					return;
				}
				unmatched.pop();
			}
		}

		super.selectFail(name, route);
	}
}
exports.ModuleVersionSymbolsSelect = ModuleVersionSymbolsSelect;

class FileSelect extends ContentSelect {
	/**
	 * @param {!Module} module
	 * @param {!ModuleVersion} moduleVersion
	 * @param {!File} file
	 * @param {!Map<string, {file: !File, sym: !Symbol}>} symbolIndex
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(module, moduleVersion, file, symbolIndex, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const */
		this.module_ = module;

		/** @private @const */
		this.moduleVersion_ = moduleVersion;

		/** @private @const */
		this.file_ = file;

		/** @private @const @type {!Map<string, {file: !File, sym: !Symbol}>} */
		this.symbolIndex_ = symbolIndex;
	}

	/**
	 * @returns {!File}
	 */
	getFile() {
		return this.file_;
	}

	/**
	 * @override
	 */
	createDom() {
		this.setElementInternal(
			soy.renderAsElement(
				fileInfoSelect,
				{
					moduleVersion: this.moduleVersion_,
					file: this.file_,
				},
				{
					baseUrl: this.getPathUrl(),
				},
			),
		);
	}

	/** @override */
	enterDocument() {
		super.enterDocument();

		formatMarkdownAll(this.getElementStrict());
	}

	/**
	 * @override
	 * @param {!Route} route
	 */
	goHere(route) {
		// Synthetic pseudo-module files (e.g. @_builtins's "globals", "cpp")
		// have no upstream source to fetch — the BzlFileSourceComponent would
		// 404. Land on the symbol list instead. Heuristic: files whose label
		// name doesn't end in .bzl aren't real source files.
		const labelName = this.file_.getLabel()?.getName() || "";
		const tab = labelName.endsWith(".bzl") ? TabName.SOURCE : TabName.LIST;
		this.select(tab, route.add(tab));
	}

	/**
	 * @override
	 * @param {string} name
	 * @param {!Route} route
	 */
	selectFail(name, route) {
		if (name === TabName.LIST) {
			this.addTab(
				name,
				new FileListComponent(
					this.module_,
					this.moduleVersion_,
					this.file_,
					this.dom_,
				),
			);
			this.select(name, route);
			return;
		}

		if (name === TabName.SOURCE) {
			this.addTab(
				name,
				new BzlFileSourceComponent(
					this.module_,
					this.moduleVersion_,
					this.file_,
					this.dom_,
				),
			);
			this.select(name, route);
			return;
		}

		for (const sym of this.file_.getSymbolList()) {
			if (name !== sym.getName()) {
				continue;
			}
			this.addTab(name, this.createSymbolComponent(sym));
			this.select(name, route);
			return;
		}

		super.selectFail(name, route);
	}

	/**
	 * @param {!Symbol} sym
	 * @returns {!SymbolComponent}
	 */
	createSymbolComponent(sym) {
		switch (sym.getType()) {
			case SymbolType.SYMBOL_TYPE_RULE:
				return new RuleInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_FUNCTION:
				return new FunctionInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_PROVIDER:
				return new ProviderInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_STRUCT:
				return new StructInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.symbolIndex_,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_ASPECT:
				return new AspectInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_MODULE_EXTENSION:
				return new ModuleExtensionInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_REPOSITORY_RULE:
				return new RepositoryRuleInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_MACRO:
				return new MacroInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_RULE_MACRO:
				return new RuleMacroInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_VALUE:
				return new ValueInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			case SymbolType.SYMBOL_TYPE_LOAD_STMT:
				return new LoadInfoComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
			default:
				return new SymbolComponent(
					this.moduleVersion_,
					this.file_,
					sym,
					this.dom_,
				);
		}
	}
}

