class ModuleVersionSymbolsTreeComponent extends Component {
	/**
	 * @param {!ModuleVersion} moduleVersion
	 * @param {!ModuleVersionSymbols} docs
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(moduleVersion, docs, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const */
		this.moduleVersion_ = moduleVersion;

		/** @private @const */
		this.docs_ = docs;
	}

	/**
	 * @override
	 */
	createDom() {
		// Build a tree structure from the files based on load dependencies
		const tree = this.buildFileTree_();

		this.setElementInternal(
			soy.renderAsElement(
				fileInfoTreeComponent,
				{
					moduleVersion: this.moduleVersion_,
					tree: tree,
				},
				{
					baseUrl: path.dirname(this.getPathUrl()),
				},
			),
		);
	}

	/**
	 * Build a tree structure from files based on load dependencies.
	 * @return {!FileLoadTree} Tree structure with root files and their dependencies
	 * @private
	 */
	buildFileTree_() {
		const files = this.docs_.getFileList().filter(isPublicFile);
		// const files = this.docs_.getFileList();

		// Create a map of file label to File for quick lookup
		/** @type {!Map<string, !File>} */
		const fileMap = new Map();
		for (const file of files) {
			const label = file.getLabel();
			if (label) {
				const key = this.getLabelKey_(label);
				fileMap.set(key, file);
			}
		}

		// Build adjacency list for load dependencies (within module only)
		/** @type {!Map<string, !Array<string>>} */
		const dependencies = new Map();
		/** @type {!Map<string, !Array<string>>} */
		const dependents = new Map();

		for (const file of files) {
			const fileKey = this.getLabelKey_(file.getLabel());
			dependencies.set(fileKey, []);

			// Find load statements in the symbol list
			for (const sym of file.getSymbolList()) {
				if (sym.getType() === SymbolType.SYMBOL_TYPE_LOAD_STMT) {
					const load = sym.getLoad();
					if (!load) continue;
					const loadLabel = load.getLabel();
					// Only include loads from the same package (within module)
					if (loadLabel && this.isInternalLoad_(file.getLabel(), loadLabel)) {
						const loadKey = this.getLabelKey_(loadLabel);
						console.log("Processing load:", {
							file: fileKey,
							loadKey: loadKey,
							hasFile: fileMap.has(loadKey),
							availableFiles: Array.from(fileMap.keys()),
						});
						if (fileMap.has(loadKey)) {
							dependencies.get(fileKey).push(loadKey);

							if (!dependents.has(loadKey)) {
								dependents.set(loadKey, []);
							}
							dependents.get(loadKey).push(fileKey);
						}
					}
				}
			}
		}

		// Find root files (files that are not loaded by any other file in the module)
		/** @type {!Array<!FileLoadTreeNode>} */
		const rootNodes = [];
		for (const file of files) {
			const fileKey = this.getLabelKey_(file.getLabel());
			if (!dependents.has(fileKey) || dependents.get(fileKey).length === 0) {
				const node = this.buildTreeNode_(
					file,
					fileKey,
					dependencies,
					fileMap,
					new Set(),
				);
				rootNodes.push(node);
			}
		}

		const tree = new FileLoadTree();
		tree.setRootsList(rootNodes);
		return tree;
	}

	/**
	 * Recursively build a file tree node.
	 * @param {!File} file
	 * @param {string} fileKey
	 * @param {!Map<string, !Array<string>>} dependencies
	 * @param {!Map<string, !File>} fileMap
	 * @param {!Set<string>} visited
	 * @return {!FileLoadTreeNode}
	 * @private
	 */
	buildTreeNode_(file, fileKey, dependencies, fileMap, visited) {
		const node = new FileLoadTreeNode();
		node.setFile(file);

		if (visited.has(fileKey)) {
			node.setPruned(true);
			return node;
		}

		visited.add(fileKey);
		/** @type {!Array<!FileLoadTreeNode>} */
		const children = [];
		const deps = dependencies.get(fileKey) || [];

		for (const depKey of deps) {
			const childFile = fileMap.get(depKey);
			if (childFile) {
				const childNode = this.buildTreeNode_(
					childFile,
					depKey,
					dependencies,
					fileMap,
					new Set(visited),
				);
				children.push(childNode);
			}
		}

		node.setChildrenList(children);
		return node;
	}

	/**
	 * Get a normalized key for a label.
	 * @param {?Label} label
	 * @return {string}
	 * @private
	 */
	getLabelKey_(label) {
		if (!label) return "";
		const pkg = label.getPkg() || "";
		const name = label.getName() || "";
		return pkg ? `${pkg}/${name}` : name;
	}

	/**
	 * Check if a load is internal to the module (same repo, no external deps).
	 * @param {?Label} fileLabel
	 * @param {?Label} loadLabel
	 * @return {boolean}
	 * @private
	 */
	isInternalLoad_(fileLabel, loadLabel) {
		if (!loadLabel) return false;
		if (fileLabel.getRepo() !== loadLabel.getRepo()) {
			return false;
		}
		// Internal loads should have the same package structure
		return true;
	}
}

class FileListComponent extends MarkdownComponent {
	/**
	 * @param {!Module} module
	 * @param {!ModuleVersion} moduleVersion
	 * @param {!File} file
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(module, moduleVersion, file, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const */
		this.module_ = module;

		/** @private @const */
		this.moduleVersion_ = moduleVersion;

		/** @private @const */
		this.file_ = file;
	}

	/**
	 * @override
	 */
	createDom() {
		// Construct symbol lists by type
		const rules = [];
		const funcs = [];
		const providers = [];
		const aspects = [];
		const moduleExtensions = [];
		const repositoryRules = [];
		const macros = [];
		const ruleMacros = [];
		const loads = [];
		const values = [];
		const structs = [];

		for (const sym of this.file_.getSymbolList()) {
			switch (sym.getType()) {
				case SymbolType.SYMBOL_TYPE_RULE:
					rules.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_FUNCTION:
					funcs.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_PROVIDER:
					providers.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_ASPECT:
					aspects.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_MODULE_EXTENSION:
					moduleExtensions.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_REPOSITORY_RULE:
					repositoryRules.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_MACRO:
					macros.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_RULE_MACRO:
					ruleMacros.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_LOAD_STMT:
					loads.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_VALUE:
					values.push(sym);
					break;
				case SymbolType.SYMBOL_TYPE_STRUCT:
					structs.push(sym);
					break;
			}
		}

		this.setElementInternal(
			soy.renderAsElement(
				fileInfoListComponent,
				{
					moduleVersion: this.moduleVersion_,
					file: this.file_,
					rules: rules,
					funcs: funcs,
					providers: providers,
					aspects: aspects,
					moduleExtensions: moduleExtensions,
					repositoryRules: repositoryRules,
					macros: macros,
					ruleMacros: ruleMacros,
					loads: loads,
					values: values,
					structs: structs,
				},
				{
					baseUrl: path.join(
						"modules",
						this.moduleVersion_.getName(),
						this.moduleVersion_.getVersion(),
						"docs",
					),
				},
			),
		);
	}

	/** @override */
	enterDocument() {
		super.enterDocument();

		highlightAll(this.getElementStrict());
	}
}

class DocumentationReadmeComponent extends MarkdownComponent {
	/**
	 * @param {!Module} module
	 * @param {!ModuleVersion} moduleVersion
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(module, moduleVersion, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const @type {!Module} */
		this.module_ = module;

		/** @private @const @type {!ModuleVersion} */
		this.moduleVersion_ = moduleVersion;

		/** @private @type {boolean} */
		this.loading_ = true;

		/** @private @type {?string} */
		this.readmeContent_ = null;

		/** @private @type {?string} */
		this.error_ = null;

		/** @private @type {?string} */
		this.readmeFilename_ = null;
	}

	/**
	 * @override
	 */
	createDom() {
		this.setElementInternal(
			soy.renderAsElement(documentationReadmeComponent, {
				moduleVersion: this.moduleVersion_,
				loading: this.loading_,
				error: this.error_ || undefined,
				content: this.readmeContent_ || undefined,
			}),
		);
	}

	/**
	 * @override
	 */
	enterDocument() {
		super.enterDocument();

		this.fetchReadme_();
	}

	/**
	 * Resolve the GitHub org/repo/commitSha for the current module version.
	 * Falls back to the latest version's commit SHA, then to "HEAD" so a
	 * tag-only source.json (no `commit` field) still produces usable URLs.
	 * @return {?{org: string, repo: string, commitSha: string}}
	 * @private
	 */
	getGithubRef_() {
		const metadata = this.moduleVersion_.getRepositoryMetadata();
		if (!metadata || metadata.getType() !== RepositoryType.GITHUB) {
			return null;
		}
		let commitSha = this.moduleVersion_.getSource()?.getCommitSha();
		if (!commitSha) {
			const latestVersion = getLatestModuleVersion(this.module_);
			commitSha = latestVersion?.getSource()?.getCommitSha();
		}
		if (!commitSha) {
			commitSha = "HEAD";
		}
		return {
			org: metadata.getOrganization(),
			repo: metadata.getName(),
			commitSha,
		};
	}

	/**
	 * Fetch README.md from GitHub for the specific commit
	 * @private
	 */
	fetchReadme_() {
		const ref = this.getGithubRef_();
		if (!ref) {
			this.error_ = "README is only available for GitHub repositories";
			this.loading_ = false;
			this.updateDom_();
			return;
		}

		// Try common README filename variations (order matters - try most common first)
		const readmeFilenames = [
			"README.md",
			"readme.md",
			"Readme.md",
			"README.rst",
			"readme.rst",
			"README.markdown",
			"README",
		];

		this.tryFetchReadme_(ref.org, ref.repo, ref.commitSha, readmeFilenames, 0);
	}

	/**
	 * Try fetching README with different filename variations
	 * @param {string} org
	 * @param {string} repo
	 * @param {string} commitSha
	 * @param {!Array<string>} filenames
	 * @param {number} index
	 * @private
	 */
	tryFetchReadme_(org, repo, commitSha, filenames, index) {
		if (index >= filenames.length) {
			this.error_ = "README not found";
			this.loading_ = false;
			this.updateDom_();
			return;
		}

		const filename = filenames[index];
		const readmeUrl = `https://raw.githubusercontent.com/${org}/${repo}/${commitSha}/${filename}`;

		// Create an AbortController for timeout
		const controller = new AbortController();
		const timeoutId = setTimeout(() => controller.abort(), 10000);

		fetch(readmeUrl, { signal: controller.signal })
			.then((response) => {
				clearTimeout(timeoutId);
				if (this.isDisposed()) return null;
				if (!response.ok) {
					// Try next filename
					this.tryFetchReadme_(org, repo, commitSha, filenames, index + 1);
					return null;
				}
				return response.text();
			})
			.then(
				/**
				 * Success callback
				 * @param {?string} content
				 */
				(content) => {
					if (this.isDisposed()) return;
					if (content !== null) {
						this.readmeContent_ = content;
						this.readmeFilename_ = filename;
						this.loading_ = false;
						this.updateDom_();
					}
				},
			)
			.catch((err) => {
				clearTimeout(timeoutId);
				if (this.isDisposed()) return;
				if (err instanceof Error && err.name === "AbortError") {
					this.error_ = "README fetch timed out after 10 seconds";
					this.loading_ = false;
					this.updateDom_();
				} else {
					// Try next filename on error
					this.tryFetchReadme_(org, repo, commitSha, filenames, index + 1);
				}
			});
	}

	/**
	 * Update the DOM with new content
	 * @private
	 */
	updateDom_() {
		const newElement = soy.renderAsElement(documentationReadmeComponent, {
			moduleVersion: this.moduleVersion_,
			loading: this.loading_,
			error: this.error_ || undefined,
			content: this.readmeContent_ || undefined,
		});

		if (this.getElement()) {
			dom.replaceNode(newElement, this.getElement());
			this.setElementInternal(newElement);

			// Format content based on file type
			const isRst =
				this.readmeFilename_ &&
				this.readmeFilename_.toLowerCase().endsWith(".rst");
			if (isRst) {
				this.formatRst_();
			} else {
				// Re-format markdown after update
				formatMarkdownAll(this.getElementStrict());
			}

			// Rewrite relative links to point to GitHub
			this.rewriteReadmeLinks_();
		}
	}

	/**
	 * Format RST content
	 * @private
	 */
	formatRst_() {
		const rootEl = this.getElementStrict();
		const divEls = dom.findElements(rootEl, (el) =>
			dom.classlist.contains(el, goog.getCssName("marked")),
		);

		arrays.forEach(divEls, (el) => {
			const rstContent = el.textContent;

			// For now, render as preformatted text with a note
			// TODO: Add proper RST parser (e.g., restructured npm package)
			const html = `
                <pre style="background: #f6f8fa; border-radius: 6px; overflow-x: auto;">${this.escapeHtml_(rstContent)}</pre>
            `;

			setElementInnerHtml(el, sanitizeHtml(html));
		});
	}

	/**
	 * Escape HTML special characters
	 * @param {string} text
	 * @return {string}
	 * @private
	 */
	escapeHtml_(text) {
		const div = document.createElement("div");
		div.textContent = text;
		return div.innerHTML;
	}

	/**
	 * Rewrite relative links in the README to point to GitHub
	 * @private
	 */
	rewriteReadmeLinks_() {
		const ref = this.getGithubRef_();
		if (!ref) {
			return;
		}

		const githubBase = `https://github.com/${ref.org}/${ref.repo}`;
		const githubBlobBase = `${githubBase}/blob/${ref.commitSha}`;
		const githubRawBase = `https://raw.githubusercontent.com/${ref.org}/${ref.repo}/${ref.commitSha}`;

		const rootEl = this.getElement();
		if (!rootEl) return;

		// Rewrite links
		const links = rootEl.querySelectorAll("a[href]");
		for (const link of links) {
			const href = link.getAttribute("href");
			if (!href) continue;

			// Skip absolute URLs
			if (
				href.startsWith("http://") ||
				href.startsWith("https://") ||
				href.startsWith("//")
			) {
				continue;
			}

			// Skip anchors and mailto
			if (href.startsWith("#") || href.startsWith("mailto:")) {
				continue;
			}

			// Rewrite relative URLs to GitHub blob URLs
			const newHref = `${githubBlobBase}/${href.replace(/^\.\//, "")}`;
			link.setAttribute("href", newHref);
			link.setAttribute("target", "_blank");
			link.setAttribute("rel", "noopener noreferrer");
		}

		// Rewrite image sources
		const images = rootEl.querySelectorAll("img[src]");
		for (const img of images) {
			const src = img.getAttribute("src");
			if (!src) continue;

			// Skip absolute URLs
			if (
				src.startsWith("http://") ||
				src.startsWith("https://") ||
				src.startsWith("//")
			) {
				continue;
			}

			// Rewrite relative URLs to GitHub raw URLs
			const newSrc = `${githubRawBase}/${src.replace(/^\.\//, "")}`;
			img.setAttribute("src", newSrc);
		}
	}
}
exports.DocumentationReadmeComponent = DocumentationReadmeComponent;

class BzlFileSourceComponent extends GitHubSourceFileComponent {
	/**
	 * @param {!Module} module
	 * @param {!ModuleVersion} moduleVersion
	 * @param {!File} file
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(module, moduleVersion, file, opt_domHelper) {
		// Extract file path from the label
		const label = file.getLabel();
		const pkg = label?.getPkg();
		const name = label?.getName();
		const filePath = pkg ? `${pkg}/${name}` : name || "";

		super(
			module,
			moduleVersion,
			filePath,
			bzlFileSourceComponent,
			{ file },
			opt_domHelper,
		);

		// Files listed in source.json's overlay map don't live in the upstream
		// repo — they're served from bazel-central-registry under
		// modules/<name>/<version>/overlay/. Detect the overlay case here so
		// fetchSource_/updateDom_ can route to the BCR archive on GitHub.
		const overlayMap = moduleVersion.getSource()?.getOverlayMap();
		/** @private @const @type {boolean} */
		this.isOverlayFile_ = !!overlayMap && overlayMap.has(filePath);
	}

	/**
	 * Compute raw + blob URLs against the bazel-central-registry archive at
	 * its pinned submodule SHA. Returns null if the registry's repository URL
	 * isn't a recognized github.com pattern.
	 * @return {?{rawUrl: string, blobUrl: string}}
	 * @private
	 */
	overlayUrls_() {
		const registry = getApplication(this).getRegistry();
		const repoUrl = registry.getRepositoryUrl();
		const sha = registry.getCommitSha();
		if (!repoUrl || !sha) return null;
		const parsed = parseGitHubRepoUrl(repoUrl);
		if (!parsed) return null;
		const path = `modules/${this.moduleVersion_.getName()}/${this.moduleVersion_.getVersion()}/overlay/${this.filePath_}`;
		return {
			rawUrl: `https://raw.githubusercontent.com/${parsed.owner}/${parsed.repo}/${sha}/${path}`,
			blobUrl: `https://github.com/${parsed.owner}/${parsed.repo}/blob/${sha}/${path}`,
		};
	}

	/** @override */
	fetchSource_() {
		if (!this.isOverlayFile_) {
			super.fetchSource_();
			return;
		}
		const overlay = this.overlayUrls_();
		if (!overlay) {
			super.fetchSource_();
			return;
		}
		this.templateData_ = {
			...(this.templateData_ || {}),
			overlaySourceUrl: overlay.blobUrl,
		};
		this.fetchAndRender_(overlay.rawUrl);
	}
}

/**
 * Component that displays documentation symbol search results.
 */
class DocumentationSearchComponent extends ContentComponent {
	/**
	 * @param {!Registry} registry
	 * @param {?dom.DomHelper=} opt_domHelper
	 */
	constructor(registry, opt_domHelper) {
		super(opt_domHelper);

		/** @private @const @type {!Registry} */
		this.registry_ = registry;

		/** @private @type {?HTMLInputElement} */
		this.searchInput_ = null;
	}

	/**
	 * @override
	 */
	createDom() {
		this.setElementInternal(soy.renderAsElement(documentationSearchComponent));
	}

	/**
	 * @override
	 * @return {Element}
	 */
	getContentElement() {
		return this.getCssElement(goog.getCssName("search-results"));
	}

	/**
	 * @override
	 */
	enterDocument() {
		super.enterDocument();

		this.searchInput_ = /** @type {?HTMLInputElement} */ (
			this.getElementStrict().querySelector(".js-search-input")
		);

		if (this.searchInput_) {
			this.getHandler().listen(
				this.searchInput_,
				events.EventType.INPUT,
				this.handleSearchInput_,
			);
		}
	}

	/**
	 * Handle input events on the dedicated search box.
	 * @param {!events.Event} e
	 * @private
	 */
	handleSearchInput_(e) {
		const value = this.searchInput_.value.trim();
		if (!value) {
			const el = this.getContentElement();
			dom.removeChildren(el);
			return;
		}
		const tokens = value.split(/\s+/);
		const results = this.searchSymbols(tokens);
		const el = this.getContentElement();
		soy.renderElement(el, searchSymbolsResultsList, { tokens, results });
	}

	/**
	 * @override
	 * @param {!Route} route
	 */
	goDown(route) {
		const tokens = route.unmatchedPath();
		const results = this.searchSymbols(tokens);
		const el = this.getContentElement();
		soy.renderElement(el, searchSymbolsResultsList, { tokens, results });

		// Pre-fill the search input with the query
		if (this.searchInput_) {
			this.searchInput_.value = tokens.join(" ");
		}

		route.done(this);
	}

	/**
	 * Search symbols by matching tokens against names and descriptions.
	 * Supports prefix filters like "r:foo" to filter by symbol type.
	 * @param {!Array<string>} tokens
	 * @return {!Array<!SymbolSearchResult>}
	 */
	searchSymbols(tokens) {
		/** @type {!Array<!SymbolSearchResult>} */
		const results = [];

		// Parse tokens for type prefixes
		const { typeFilters, queryTokens } = this.parseSearchTokens_(tokens);

		/** @type {!Array<string>} */
		const lowerTokens = queryTokens.map((t) => t.toLowerCase());

		// If no query tokens remain after prefix parsing, return empty
		if (lowerTokens.length === 0) {
			return results;
		}

		for (const module of this.registry_.getModulesList()) {
			const version = module.getVersionsList()[0]; // search most recent version only
			const docs = version.getSource()?.getDocumentation();
			if (!docs) continue;

			for (const file of docs.getFileList()) {
				if (file.getError() || !isPublicFile(file)) continue;

				for (const sym of file.getSymbolList()) {
					const symType = sym.getType();
					// Skip LOAD and VALUE symbols
					if (
						symType === SymbolType.SYMBOL_TYPE_LOAD_STMT ||
						symType === SymbolType.SYMBOL_TYPE_VALUE
					) {
						continue;
					}

					// Check type filter if present
					if (typeFilters.length > 0 && !typeFilters.includes(symType)) {
						continue;
					}

					const symName = sym.getName().toLowerCase();

					if (lowerTokens.some((t) => symName.includes(t))) {
						results.push({
							module,
							version,
							file,
							sym,
						});
					}
				}
			}
		}
		return results;
	}

	/**
	 * Parse search tokens for type prefix filters.
	 * Prefixes like "r:foo" filter by symbol type.
	 * @param {!Array<string>} tokens
	 * @return {{typeFilters: !Array<number>, queryTokens: !Array<string>}}
	 * @private
	 */
	parseSearchTokens_(tokens) {
		/** @type {!Array<number>} */
		const typeFilters = [];
		/** @type {!Array<string>} */
		const queryTokens = [];

		for (const token of tokens) {
			const colonIdx = token.indexOf(":");
			if (colonIdx > 0 && colonIdx < token.length - 1) {
				const prefix = token.substring(0, colonIdx).toLowerCase();
				const query = token.substring(colonIdx + 1);

				const types = SYMBOL_TYPE_PREFIXES.get(prefix);
				if (types) {
					for (const t of types) {
						if (!typeFilters.includes(t)) {
							typeFilters.push(t);
						}
					}
					queryTokens.push(query);
					continue;
				}
			}
			// No valid prefix, treat as regular query token
			queryTokens.push(token);
		}

		return { typeFilters, queryTokens };
	}
}
exports.DocumentationSearchComponent = DocumentationSearchComponent;

/**
 * Build symbol groups for a file, organized by type.
 * @param {!File} file
 * @return {!Array<SymbolGroup>}
 */
function buildSymbolGroupsForFile(file) {
	/** @type {!Array<SymbolGroup>} */
	const symbolGroups = [];

	/** @type {!Map<SymbolType,SymbolGroup>} */
	const symbolsByType = new Map();

	// Group symbols by type
	for (const sym of file.getSymbolList()) {
		const type = sym.getType();
		let group = symbolsByType.get(type);
		if (!group) {
			const typeName = soy.renderAsText(symbolTypeName, { type });
			group = { type, typeName, symbols: [] };
			symbolsByType.set(type, group);
		}
		group.symbols.push(sym);
	}

	// Build groups array with only non-empty groups
	for (const group of symbolsByType.values()) {
		if (group.symbols.length > 0) {
			group.typeName += "s";
			symbolGroups.push(group);
		}
	}

	return symbolGroups;
}

/**
 * Compute extraction completeness stats from a ModuleVersionSymbols proto.
 * Counts files with non-empty `error` to derive a success rate. Operates on
 * the same set displayed in the file list (public files plus any error files)
 * so the numerator and denominator match what the user sees.
 * @param {!ModuleVersionSymbols} docs
 * @return {{success: number, total: number, pct: number, pctText: string}}
 */
function computeExtractionStats(docs) {
	const files = docs
		.getFileList()
		.filter((file) => isPublicFile(file) || !!file.getError());
	const total = files.length;
	let errors = 0;
	for (const file of files) {
		if (file.getError()) errors++;
	}
	const success = total - errors;
	const pct = total > 0 ? (success / total) * 100 : 0;
	return { success, total, pct, pctText: pct.toFixed(1) };
}

/**
 * Build file symbol groups for all public files in documentation.
 * Files with extraction errors are always included so the user can investigate.
 * @param {!ModuleVersionSymbols} docs
 * @return {!Array<FileSymbolGroupList>}
 */
function buildFileSymbolGroups(docs) {
	const files = docs
		.getFileList()
		.filter((file) => isPublicFile(file) || !!file.getError());

	// Build symbol groups for each file
	/** @type {!Array<FileSymbolGroupList>} */
	const fileSymbols = files.map((file) => ({
		file,
		symbolGroups: buildSymbolGroupsForFile(file),
	}));

	fileSymbols.sort(
		/**
		 * @param {FileSymbolGroupList} a
		 * @param {FileSymbolGroupList} b
		 * @returns {number}
		 */
		(a, b) => {
			const aHasError = a.file.getError() ? 1 : 0;
			const bHasError = b.file.getError() ? 1 : 0;

			// Files with errors go to the end
			if (aHasError !== bHasError) {
				return aHasError - bHasError;
			}

			// Otherwise, stable sort (return 0 to maintain original order)
			return 0;
		},
	);

	return fileSymbols;
}

/**
 * Build nav symbol groups aggregated across all files by type.
 * Used for the sidebar navigation which shows type -> symbol (no file grouping).
 * @param {!Array<FileSymbolGroupList>} fileSymbols
 * @return {!Array<NavSymbolGroup>}
 */
function buildNavSymbolGroups(fileSymbols) {
	/** @type {!Map<SymbolType, NavSymbolGroup>} */
	const groupsByType = new Map();

	for (const fileSymbolGroup of fileSymbols) {
		const file = fileSymbolGroup.file;
		if (file.getError()) {
			continue;
		}
		for (const symbolGroup of fileSymbolGroup.symbolGroups) {
			if (symbolGroup.type === SymbolType.SYMBOL_TYPE_LOAD_STMT) {
				continue;
			}
			let navGroup = groupsByType.get(symbolGroup.type);
			if (!navGroup) {
				navGroup = {
					type: symbolGroup.type,
					typeName: symbolGroup.typeName,
					items: [],
				};
				groupsByType.set(symbolGroup.type, navGroup);
			}
			for (const sym of symbolGroup.symbols) {
				navGroup.items.push({ file, sym });
			}
		}
	}

	for (const group of groupsByType.values()) {
		group.items.sort(bySymbolName);
	}

	/** @type {!Array<NavSymbolGroup>} */
	const result = Array.from(groupsByType.values());
	result.sort(
		/**
		 * @param {NavSymbolGroup} a
		 * @param {NavSymbolGroup} b
		 * @returns {number}
		 */
		(a, b) => a.type - b.type,
	);
	return result;
}

/**
 * Sorts file-symbol pairs by symbol name alphabetically.
 * @param {!FileSymbol} a
 * @param {!FileSymbol} b
 * @return {number}
 */
function bySymbolName(a, b) {
	return a.sym.getName().localeCompare(b.sym.getName());
}

/**
 * Returns true if the file should be included in public documentation.
 * Filters out files in /private/ or /internal/ directories.
 * @param {!File} file
 * @return {boolean}
 */
function isPublicFile(file) {
	const label = file.getLabel();
	if (!label) {
		return true;
	}
	const pkg = label.getPkg() || "";
	const name = label.getName() || "";
	const path = pkg ? `${pkg}/${name}` : name;

	return !(
		path.includes("private/") ||
		path.includes("internal/") ||
		path.includes("thirdparty/") ||
		path.includes("third_party/") ||
		path.includes("examples/") ||
		path.includes("example/") ||
		path.includes("tests/") ||
		path.includes("vendor/") ||
		path.includes("test/")
	);
}

/**
 *
 * @param {!Element} rootEl The root element to search from
 */
